-- Curated pet-diet ingredients for the mix builder. Per 100 g. Source: USDA FoodData Central (SR Legacy 2018, Foundation Foods 2026-04), public domain.
-- GENERATED by supabase/scripts/build_ingredients.py; rerun it instead of editing. Calcium or phosphorus left null means USDA does not report it.
create table if not exists ref.ingredients (
  id text primary key,
  name text not null,
  group_name text not null,
  state text not null check (state in ('raw','cooked','canned','oil','water','supplement')),
  source text not null,
  fdc_id bigint,
  usda_description text,
  kcal numeric not null,
  protein_g numeric not null,
  fat_g numeric not null,
  calcium_mg numeric,
  phosphorus_mg numeric,
  water_g numeric,
  fiber_g numeric
);
alter table ref.ingredients enable row level security;
do $$ begin create policy "public read" on ref.ingredients for select to anon, authenticated using (true); exception when duplicate_object then null; end $$;
grant usage on schema ref to anon, authenticated;
grant select on ref.ingredients to anon, authenticated;
on conflict (id) do update set name = excluded.name, kcal = excluded.kcal, protein_g = excluded.protein_g, fat_g = excluded.fat_g, calcium_mg = excluded.calcium_mg, phosphorus_mg = excluded.phosphorus_mg, water_g = excluded.water_g, fiber_g = excluded.fiber_g;
